  return {
    id: nextId() as ProjectId,
    orgId: ORG_A,
    name: "Website relaunch",
    slug: "website-relaunch",
    key: "WEB",
    description: null,
    visibility: "org",
    status: "active",
    leadId: ALICE,
    color: "#6366f1",
    startsAt: null,
    targetDate: null,
    archivedAt: null,
    createdAt: EPOCH,
    updatedAt: EPOCH,
    ...overrides,
  };
}

export function makeIssue(overrides: Partial<Issue> = {}): Issue {
  return {
    id: nextId() as IssueId,
    orgId: ORG_A,
    projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP" as ProjectId,
    number: 1,
    title: "Fix the broken sign-up link",
    description: null,
    status: "todo",
    priority: "medium",
    authorId: ALICE,
    assigneeId: null,
    parentId: null,
    estimate: null,
    dueAt: null,
    startedAt: null,
    completedAt: null,
    labelIds: [],
    archivedAt: null,
    createdAt: EPOCH,
    updatedAt: EPOCH,
    ...overrides,
  };
}

export function makeComment(overrides: Partial<Comment> = {}): Comment {
  return {
    id: nextId() as CommentId,
    orgId: ORG_A,
    issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS" as IssueId,
    authorId: ALICE,
    body: "Looking at this now.",
    parentId: null,
    editedAt: null,
    mentionedUserIds: [],
    archivedAt: null,
    createdAt: EPOCH,
    updatedAt: EPOCH,
    ...overrides,
  };
}

export function makeMember(
  overrides: Partial<MemberWithUser> = {},
): MemberWithUser {
  const user = overrides.user ?? makeUser();
  return {
    id: nextId() as MemberId,
    orgId: ORG_A,
    userId: user.id,
    role: "member",
    status: "active",
    invitedBy: null,
    joinedAt: EPOCH,
    lastSeenAt: EPOCH,
    archivedAt: null,
    createdAt: EPOCH,
    updatedAt: EPOCH,
    ...overrides,
    user,
  };
}

export function makeLimitCheck(overrides: Partial<LimitCheck> = {}): LimitCheck {
  const limit = overrides.limit ?? 3;
  const used = overrides.used ?? 1;
  return {
    resource: "seats",
    plan: "free",
    limit,
    used,
    remaining: Math.max(0, limit - used),
    exceeded: used >= limit,
    ...overrides,
  };
}
