/**
 * Bulk issue import: the per-workspace ledger of import keys and the single transaction that writes a batch.
 *
 * Must call (do not reimplement): orgPredicate, highestIssueNumber
 */
import { and, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issueImports, issueLabels, issues, labels } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { highestIssueNumber } from "./issue-repository";
import { brandId, parseJsonArray } from "./_mappers";
import type { IssueImportRow } from "@/server/db";
import type {
  IsoTimestamp,
  IssueId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { IssuePriority, IssueStatus } from "@/types/issue";

/** One row of a batch, with the workspace lookups already resolved. */
export interface ImportRowPlan {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly dueAt: IsoTimestamp | null;
  /** Label names as the file spelled them; created here when the org lacks them. */
  readonly labelNames: readonly string[];
}

export interface ImportPlan {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly authorId: UserId;
  readonly rows: readonly ImportRowPlan[];
}

/** What the ledger remembers about an import. */
export interface ImportRecord {
  readonly projectId: ProjectId;
  /** In file order. */
  readonly issueIds: readonly IssueId[];
}

export async function findImport(
  orgId: OrgId,
  importKey: string,
): Promise<ImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  return row ? toRecord(row) : null;
}

/**
 * Writes a whole batch or nothing: missing labels, every issue, the label
 * joins and the ledger row commit together. Issues are numbered in file
 * order after the project's highest number, archived issues included.
 *
 * If the key turns up in the ledger inside the transaction — a concurrent
 * upload of the same file won the race — nothing is written and the earlier
 * import is reported with `replayed: true`.
 */
export async function insertImport(
  plan: ImportPlan,
): Promise<ImportRecord & { readonly replayed: boolean }> {
  return getDb().transaction((tx) => {
    const earlier = tx
      .select()
      .from(issueImports)
      .where(
        and(
          orgPredicate(issueImports.orgId, plan.orgId),
          eq(issueImports.importKey, plan.importKey),
        ),
      )
      .get();
    if (earlier) return { ...toRecord(earlier), replayed: true };

    const stamp = toIsoTimestamp(new Date());

    // Label names are matched exactly; the unique (org_id, name) index is
    // case-sensitive too. `color` and `description` are left to the column
    // defaults, the same ones a label created by hand starts from.
    const labelIdByName = new Map<string, string>(
      tx
        .select({ id: labels.id, name: labels.name })
        .from(labels)
        .where(orgPredicate(labels.orgId, plan.orgId))
        .all()
        .map((label) => [label.name, label.id]),
    );

    const issueIds: IssueId[] = [];
    let number = highestIssueNumber(plan.orgId, plan.projectId);

    for (const row of plan.rows) {
      const labelIds: string[] = [];
      for (const name of new Set(row.labelNames)) {
        let labelId = labelIdByName.get(name);
        if (labelId === undefined) {
          labelId = newId();
          tx.insert(labels)
            .values({
              id: labelId,
              orgId: plan.orgId,
              name,
              createdAt: stamp,
              updatedAt: stamp,
            })
            .run();
          labelIdByName.set(name, labelId);
        }
        labelIds.push(labelId);
      }

      number += 1;
      const issueId = newId();
      tx.insert(issues)
        .values({
          id: issueId,
          orgId: plan.orgId,
          projectId: plan.projectId,
          number,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: plan.authorId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();

      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            labelIds.map((labelId) => ({
              orgId: plan.orgId,
              issueId,
              labelId,
            })),
          )
          .run();
      }

      issueIds.push(brandId<IssueId>(issueId));
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: plan.orgId,
        importKey: plan.importKey,
        projectId: plan.projectId,
        issueIds: JSON.stringify(issueIds),
        createdAt: stamp,
      })
      .run();

    return { projectId: plan.projectId, issueIds, replayed: false };
  });
}

function toRecord(row: IssueImportRow): ImportRecord {
  return {
    projectId: brandId<ProjectId>(row.projectId),
    issueIds: parseJsonArray<IssueId>(row.issueIds),
  };
}

