new='''/** The refusal a create gets when the project's plan has no room for `requested` more. */
function assertIssueQuota(
  plan: PlanId,
  project: Project,
  used: number,
  requested: number,
): void {
  if (wouldExceedLimit(plan, "issuesPerProject", used, requested)) {
    throw new Error(
      `Plan ${plan} allows no more issues in project ${project.key}`,
    );
  }
}

/**
 * Bulk import: every row becomes an issue in `input.projectId`, in file order,
 * or none does. Gates run in order — tenant scope, a live project, the
 * `issue:create` permission — and a repeated `importKey` then short-circuits
 * to the first import's result. A fresh import must fit the project's plan
 * quota as a whole and be covered by the workspace's issue-creation rate
 * allowance (one unit per row) before a single row is written, so a refusal
 * leaves nothing behind and does not use up the key.
 *
 * The batch is announced with one `issues.imported` instead of an
 * `issue.created` per row: search, usage and the audit log follow it, while
 * notifications and webhooks deliberately do not.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const earlier = await issueImportRepo.findImport(input.orgId, input.importKey);
  if (earlier) return importResult(input.orgId, input.importKey, earlier, true);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  assertIssueQuota(org.plan, project, used, input.rows.length);

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const assignees = await memberRepo.findActiveUserIdsByEmail(
    input.orgId,
    input.rows.flatMap((row) =>
      row.assigneeEmail === null ? [] : [row.assigneeEmail],
    ),
  );

  const written = await issueImportRepo.insertImport({
    orgId: input.orgId,
    projectId: input.projectId,
    importKey: input.importKey,
    authorId: actor.userId,
    rows: input.rows.map((row) => ({
      title: row.title,
      description: row.description,
      status: row.status,
      priority: row.priority,
      assigneeId:
        row.assigneeEmail === null
          ? null
          : (assignees.get(row.assigneeEmail.toLowerCase()) ?? null),
      dueAt: row.dueAt,
      labelNames: row.labels,
    })),
  });

  const result = await importResult(
    input.orgId,
    input.importKey,
    written,
    written.replayed,
  );
  if (written.replayed) return result;

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: written.projectId,
    importKey: input.importKey,
    issueIds: written.issueIds,
  });

  return result;
}

/** Loads a recorded import's issues, in the order the file listed them. */
async function importResult(
  orgId: OrgId,
  importKey: string,
  record: issueImportRepo.ImportRecord,
  replayed: boolean,
): Promise<IssueImportResult> {
  const issues: Issue[] = [];
  for (const issueId of record.issueIds) {
    const issue = await issueRepo.findIssueById(orgId, issueId);
    if (issue) issues.push(issue);
  }
  return { importKey, projectId: record.projectId, issues, replayed };
}

