    rows: input.rows.map((row) => ({
      title: row.title,
      description: row.description,
      status: row.status,
      priority: row.priority,
      assigneeId:
        row.assigneeEmail === null
          ? null
          : (assignees.get(row.assigneeEmail.toLowerCase()) ?? null),
      dueAt: row.dueAt,
      labelNames: row.labels,
    })),
  });

  const result = await importResult(
    input.orgId,
    input.importKey,
    written,
    written.replayed,
  );
  if (written.replayed) return result;

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: written.projectId,
    importKey: input.importKey,
    issueIds: written.issueIds,
  });

  return result;
}

/** Loads a recorded import's issues, in the order the file listed them. */
async function importResult(
  orgId: OrgId,
  importKey: string,
  record: issueImportRepo.ImportRecord,
  replayed: boolean,
): Promise<IssueImportResult> {
  const issues: Issue[] = [];
  for (const issueId of record.issueIds) {
    const issue = await issueRepo.findIssueById(orgId, issueId);
    if (issue) issues.push(issue);
  }
  return { importKey, projectId: record.projectId, issues, replayed };
}

