/**
 * Bulk import: access, all-or-nothing checks, row mapping, replays and the
 * single `issues.imported` announcement with its reactive consequences.
 *
 * Event handlers are attached through `registerEventHandlers()`, exactly as
 * `instrumentation.ts` does at server start.
 */
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { and, eq } from "drizzle-orm";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { consumeRateLimit, resetRateLimits } from "@/lib/rate-limit";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { getDb, issueImports, webhookDeliveries } from "@/server/db";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { NotFoundError } from "@/server/services/_support";
import * as activityService from "@/server/services/activity-service";
import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import * as usageService from "@/server/services/usage-service";
import { importIssuesSchema } from "@/schemas/issue-import";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ImportIssueRowInput } from "@/schemas/issue-import";
import type { ProjectId, OrgId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

let cleanup: () => void;
let tenant: Tenant;
let keySeq = 0;
const detachers: Unsubscribe[] = [];

function freshKey(): string {
  keySeq += 1;
  return `import-key-${String(keySeq).padStart(4, "0")}`;
}

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

function row(
  title: string,
  overrides: Partial<Record<keyof ImportIssueRowInput, unknown>> = {},
): ImportIssueRowInput {
  return importIssuesSchema.shape.rows.element.parse({ title, ...overrides });
}

function batch(
  t: Tenant,
  rows: readonly ImportIssueRowInput[],
  importKey: string = freshKey(),
  projectId: ProjectId = t.project.id,
) {
  return { orgId: t.org.id, projectId, importKey, rows };
}

async function liveCount(t: Tenant, projectId: ProjectId = t.project.id) {
  return issueRepo.countIssues(t.org.id, projectId, { includeArchived: true });
}

async function newProject(t: Tenant, key: string, slug: string): Promise<ProjectId> {
  const project = await projectRepo.insertProject({
    orgId: t.org.id,
    name: slug,
    slug,
    key,
    description: null,
    visibility: "org",
    leadId: t.userIds.owner,
    color: "#6366f1",
    targetDate: null,
  });
  return project.id;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("importing");
  registerEventHandlers();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

beforeEach(() => {
  resetRateLimits();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

describe("access", () => {
  it("refuses an orgId outside the actor's workspace", async () => {
    const other = await createTenant("importing-other");
    const before = await liveCount(other);

    await expect(
      issueService.importIssues(tenant.actors.member, batch(other, [row("Not yours")])),
    ).rejects.toBeInstanceOf(TenantScopeError);

    expect(await liveCount(other)).toBe(before);
  });

  it("reports an unknown project, and another workspace's project, as not found", async () => {
    const other = await createTenant("importing-foreign");

    await expect(
      issueService.importIssues(
        tenant.actors.member,
        batch(tenant, [row("Nowhere")], freshKey(), "01HZZZNOSUCHPROJECT0000000" as ProjectId),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.importIssues(
        tenant.actors.member,
        batch(tenant, [row("Foreign")], freshKey(), other.project.id),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    expect(await liveCount(other)).toBe(0);
  });

  it("refuses an archived project", async () => {
    const projectId = await newProject(tenant, "ARCH", "archived-import");
    await projectRepo.archiveProject(tenant.org.id, projectId);

    await expect(
      issueService.importIssues(
        tenant.actors.member,
        batch(tenant, [row("Too late")], freshKey(), projectId),
      ),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect(await liveCount(tenant, projectId)).toBe(0);
  });

  it("needs the permission that creating an issue needs", async () => {
    const key = freshKey();
    await expect(
      issueService.importIssues(tenant.actors.viewer, batch(tenant, [row("Viewer")], key)),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    expect(await issueImportRepoFind(tenant.org.id, key)).toBeNull();
  });
});

async function issueImportRepoFind(orgId: OrgId, key: string) {
  return (
    getDb()
      .select()
      .from(issueImports)
      .where(and(eq(issueImports.orgId, orgId), eq(issueImports.importKey, key)))
      .get() ?? null
  );
}

describe("rows", () => {
  it("creates one issue per row in file order, numbered after the highest number ever used", async () => {
    const projectId = await newProject(tenant, "ROW", "rows-project");
    const first = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, projectId, { title: "Existing one" }),
    );
    const second = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, projectId, { title: "Existing two" }),
    );
    await issueRepo.archiveIssue(tenant.org.id, second.id);
    expect([first.number, second.number]).toEqual([1, 2]);

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(
        tenant,
        [
          row("Zeta first in file", {
            description: "Body",
            status: "in_progress",
            priority: "high",
            dueAt: "2026-05-01T12:00:00.000Z",
          }),
          row("Alpha second in file"),
          row("Middle third in file", { status: "done", priority: "urgent" }),
        ],
        freshKey(),
        projectId,
      ),
    );

    expect(result.replayed).toBe(false);
    expect(result.projectId).toBe(projectId);
    expect(result.issues.map((issue) => issue.number)).toEqual([3, 4, 5]);
    expect(result.issues.map((issue) => issue.title)).toEqual([
      "Zeta first in file",
      "Alpha second in file",
      "Middle third in file",
    ]);
    expect(result.issues[0]).toMatchObject({
      description: "Body",
      status: "in_progress",
      priority: "high",
      dueAt: "2026-05-01T12:00:00.000Z",
      authorId: tenant.userIds.member,
      assigneeId: null,
      parentId: null,
      estimate: null,
      archivedAt: null,
    });
    expect(result.issues[1]).toMatchObject({
      description: null,
      status: "backlog",
      priority: "none",
      dueAt: null,
    });
    expect(result.issues[2]).toMatchObject({ status: "done", priority: "urgent" });

    const next = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, projectId, { title: "Created afterwards" }),
    );
    expect(next.number).toBe(6);

    const stored = await issueRepo.findIssueById(tenant.org.id, result.issues[0]!.id);
    expect(stored).toEqual(result.issues[0]);
  });
});

describe("assignees", () => {
  it("matches active members' emails case-insensitively and leaves everything else unassigned", async () => {
    const removed = await userRepo.insertUser({
      email: "gone@importing.test",
      name: "Gone",
      passwordHash: "seed",
    });
    const removedMember = await memberRepo.insertMember(
      tenant.org.id,
      removed.id,
      "member",
      null,
    );
    await memberRepo.archiveMember(tenant.org.id, removedMember.id);

    const outsider = await userRepo.insertUser({
      email: "outsider@elsewhere.test",
      name: "Outsider",
      passwordHash: "seed",
    });
    expect(outsider.id).toBeTruthy();

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, [
        row("Assigned to admin", { assigneeEmail: "ADMIN@importing.TEST" }),
        row("Assigned to owner", { assigneeEmail: "owner@importing.test" }),
        row("Unknown address", { assigneeEmail: "nobody@importing.test" }),
        row("Not a member here", { assigneeEmail: "outsider@elsewhere.test" }),
        row("Removed member", { assigneeEmail: "gone@importing.test" }),
      ]),
    );

    expect(result.issues.map((issue) => issue.assigneeId)).toEqual([
      tenant.userIds.admin,
      tenant.userIds.owner,
      null,
      null,
      null,
    ]);
  });

  it("does not match a member of a different workspace", async () => {
    const other = await createTenant("importing-assignee-other");
    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, [row("Cross workspace", { assigneeEmail: "admin@importing-assignee-other.test" })]),
    );
    expect(other.userIds.admin).toBeTruthy();
    expect(result.issues[0]?.assigneeId).toBeNull();
  });
});

describe("labels", () => {
  it("creates missing labels once, reuses existing ones and matches case-sensitively", async () => {
    const other = await createTenant("importing-labels-other");
    const foreign = await labelRepo.insertLabel({
      orgId: other.org.id,
      name: "shared-name",
      color: "#112233",
      description: "theirs",
    });
    const existing = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "Bug",
      color: "#ff0000",
      description: "ours",
    });

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, [
        row("First labelled", { labels: ["Bug", "shared-name", "shared-name", "fresh"] }),
        row("Second labelled", { labels: ["fresh", "bug"] }),
        row("Unlabelled"),
      ]),
    );

    const labels = await labelRepo.listLabels(tenant.org.id);
    const byName = new Map(labels.map((label) => [label.name, label]));

    expect(byName.get("Bug")?.id).toBe(existing.id);
    expect(byName.get("Bug")).toMatchObject({ color: "#ff0000", description: "ours" });
    expect(labels.filter((label) => label.name === "fresh")).toHaveLength(1);
    expect(byName.get("fresh")).toMatchObject({ color: "#94a3b8", description: null });
    expect(byName.get("shared-name")?.id).not.toBe(foreign.id);
    expect(byName.has("bug")).toBe(true);

    const idsOf = (index: number) => [...(result.issues[index]?.labelIds ?? [])].sort();
    expect(idsOf(0)).toEqual(
      [existing.id, byName.get("shared-name")!.id, byName.get("fresh")!.id].sort(),
    );
    expect(idsOf(1)).toEqual([byName.get("fresh")!.id, byName.get("bug")!.id].sort());
    expect(idsOf(2)).toEqual([]);

    expect(await labelRepo.listLabels(other.org.id)).toHaveLength(1);
  });
});

describe("all or nothing", () => {
  it("refuses a batch that would push the project over the plan quota", async () => {
    const free = await createTenant("importing-quota", "free");
    for (let number = 1; number <= 95; number += 1) {
      await issueRepo.insertIssue(
        issueInput(free.org.id, free.project.id, { title: `Seed issue ${number}` }),
        free.actors.member.userId,
        number,
      );
    }
    // An archived issue does not count towards the quota.
    const archived = await issueRepo.insertIssue(
      issueInput(free.org.id, free.project.id, { title: "Archived seed" }),
      free.actors.member.userId,
      96,
    );
    await issueRepo.archiveIssue(free.org.id, archived.id);

    const key = freshKey();
    const tooMany = Array.from({ length: 6 }, (_, index) => row(`Over the top ${index}`));
    await expect(
      issueService.importIssues(free.actors.member, batch(free, tooMany, key)),
    ).rejects.toThrow(/allows no more issues/);

    expect(await liveCount(free)).toBe(96);
    expect(await issueImportRepoFind(free.org.id, key)).toBeNull();
    expect(await labelRepo.listLabels(free.org.id)).toHaveLength(0);

    // The refusal did not use up the key; the batch that fits goes through.
    const fits = await issueService.importIssues(
      free.actors.member,
      batch(free, tooMany.slice(0, 5), key),
    );
    expect(fits).toMatchObject({ replayed: false });
    expect(fits.issues).toHaveLength(5);
  });

  it("refuses a batch the issue-creation allowance does not cover, without using the key", async () => {
    const key = freshKey();
    const before = await liveCount(tenant);
    const rows = Array.from({ length: 30 }, (_, index) =>
      row(`Rate limited ${index}`, { labels: ["never-created"] }),
    );

    await consumeRateLimit(tenant.org.id, "issue:create", 40);
    await expect(
      issueService.importIssues(tenant.actors.member, batch(tenant, rows, key)),
    ).rejects.toThrow(/rate limit/i);

    expect(await liveCount(tenant)).toBe(before);
    expect(await issueImportRepoFind(tenant.org.id, key)).toBeNull();
    expect(
      (await labelRepo.listLabels(tenant.org.id)).some((label) => label.name === "never-created"),
    ).toBe(false);

    // The refused batch spent nothing: 20 units are still there.
    const retry = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, rows.slice(0, 20), key),
    );
    expect(retry.replayed).toBe(false);
    expect(retry.issues).toHaveLength(20);
  });

  it("does not spend the allowance on a refused quota check or on a replay", async () => {
    const key = freshKey();
    await issueService.importIssues(tenant.actors.member, batch(tenant, [row("Spend one")], key));
    const drained = await consumeRateLimit(tenant.org.id, "issue:create", 0);

    await issueService.importIssues(tenant.actors.member, batch(tenant, [row("Spend one")], key));
    const afterReplay = await consumeRateLimit(tenant.org.id, "issue:create", 0);

    expect(afterReplay.remaining).toBe(drained.remaining);
  });
});

describe("replays", () => {
  it("returns the first import's issues and creates nothing", async () => {
    const key = freshKey();
    const first = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, [row("Replay me one"), row("Replay me two", { labels: ["replayed"] })], key),
    );
    const total = await liveCount(tenant);

    const again = await issueService.importIssues(
      tenant.actors.admin,
      batch(tenant, [row("Completely different")], key),
    );

    expect(again.replayed).toBe(true);
    expect(again.importKey).toBe(key);
    expect(again.projectId).toBe(first.projectId);
    expect(again.issues).toEqual(first.issues);
    expect(await liveCount(tenant)).toBe(total);
  });

  it("treats another key with identical rows as a new import", async () => {
    const rows = [row("Same rows")];
    const one = await issueService.importIssues(tenant.actors.member, batch(tenant, rows));
    const two = await issueService.importIssues(tenant.actors.member, batch(tenant, rows));

    expect(two.replayed).toBe(false);
    expect(two.issues[0]?.id).not.toBe(one.issues[0]?.id);
    expect(two.issues[0]?.number).toBe((one.issues[0]?.number ?? 0) + 1);
  });

  it("scopes keys to the workspace", async () => {
    const other = await createTenant("importing-keys-other");
    const key = freshKey();

    const mine = await issueService.importIssues(tenant.actors.member, batch(tenant, [row("Mine")], key));
    const theirs = await issueService.importIssues(other.actors.member, batch(other, [row("Theirs")], key));

    expect(mine.replayed).toBe(false);
    expect(theirs.replayed).toBe(false);
    expect(theirs.issues[0]?.orgId).toBe(other.org.id);
  });

  it("settles concurrent uploads of one key into a single import", async () => {
    const key = freshKey();
    const before = await liveCount(tenant);

    const results = await Promise.all([
      issueService.importIssues(tenant.actors.member, batch(tenant, [row("Racing one"), row("Racing two")], key)),
      issueService.importIssues(tenant.actors.member, batch(tenant, [row("Racing one"), row("Racing two")], key)),
    ]);

    expect(results.map((result) => result.replayed).sort()).toEqual([false, true]);
    expect(results[0].issues.map((i) => i.id)).toEqual(results[1].issues.map((i) => i.id));
    expect(await liveCount(tenant)).toBe(before + 2);
  });
});

describe("announcements", () => {
  it("publishes one issues.imported for the batch and no issue.created", async () => {
    const imported = capture("issues.imported");
    const created = capture("issue.created");
    const assigned = capture("issue.assigned");

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, [
        row("Announce one", { assigneeEmail: "admin@importing.test" }),
        row("Announce two"),
        row("Announce three"),
      ]),
    );

    expect(imported).toHaveLength(1);
    expect(imported[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      projectId: tenant.project.id,
      importKey: result.importKey,
      issueIds: result.issues.map((issue) => issue.id),
    });
    expect(created).toHaveLength(0);
    expect(assigned).toHaveLength(0);

    await issueService.importIssues(tenant.actors.member, batch(tenant, [row("Ignored")], result.importKey));
    expect(imported).toHaveLength(1);
  });

  it("publishes nothing for a refused import", async () => {
    const imported = capture("issues.imported");
    await expect(
      issueService.importIssues(tenant.actors.viewer, batch(tenant, [row("Refused")])),
    ).rejects.toThrow();
    expect(imported).toHaveLength(0);
  });

  it("makes the issues searchable, moves the usage meter and writes one audit entry", async () => {
    const importer: Actor = tenant.actors.member;
    await usageService.recomputeUsage(tenant.org.id);
    const usageBefore = await usageService.getUsage(importer, tenant.org.id);
    const auditBefore = await activityService.listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
    });

    const result = await issueService.importIssues(
      importer,
      batch(tenant, [row("Quokka migration plan"), row("Wombat cleanup", { description: "quokka mentioned" })]),
    );

    const hits = await searchService.search(importer, {
      orgId: tenant.org.id,
      q: "quokka",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(hits.items.map((hit) => hit.id).sort()).toEqual(
      result.issues.map((issue) => issue.id).sort(),
    );

    const usageAfter = await usageService.getUsage(importer, tenant.org.id);
    expect(usageAfter.issuesUsed).toBe(usageBefore.issuesUsed + 2);
    const recount = await usageService.recomputeUsage(tenant.org.id);
    expect(recount.issuesUsed).toBe(usageAfter.issuesUsed);

    const auditAfter = await activityService.listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
    });
    const fresh = auditAfter.items.filter(
      (event) => !auditBefore.items.some((old) => old.id === event.id),
    );
    expect(fresh).toHaveLength(1);
    expect(fresh[0]).toMatchObject({
      action: "issues.imported",
      actorId: tenant.userIds.member,
      subjectKind: "project",
      subjectId: tenant.project.id,
      projectId: tenant.project.id,
      metadata: { count: 2, importKey: result.importKey },
    });
  });

  it("notifies nobody and queues no webhook delivery, even for issue subscribers", async () => {
    await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://hooks.example.test/issues",
        eventTypes: ["issue.created", "issue.assigned", "issue.status_changed"],
      },
      "secret",
    );
    const deliveriesBefore = getDb()
      .select()
      .from(webhookDeliveries)
      .where(eq(webhookDeliveries.orgId, tenant.org.id))
      .all().length;
    const notificationsBefore = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      limit: 100,
      cursor: null,
    } as never);

    await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, [row("Quiet import", { assigneeEmail: "admin@importing.test" })]),
    );

    const deliveriesAfter = getDb()
      .select()
      .from(webhookDeliveries)
      .where(eq(webhookDeliveries.orgId, tenant.org.id))
      .all().length;
    expect(deliveriesAfter).toBe(deliveriesBefore);

    const notificationsAfter = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      limit: 100,
      cursor: null,
    } as never);
    expect(notificationsAfter.total).toBe(notificationsBefore.total);
  });
});

